static unsigned int d3u_ld8(dec3w_ctx *c, unsigned long a)
{
    return *d3u_ptr(c, a);
}
static void d3u_st8(dec3w_ctx *c, unsigned long a, unsigned int v)
{
    *d3u_ptr(c, a) = (unsigned char)v;
}
static unsigned int d3u_ld16(dec3w_ctx *c, unsigned long a)
{
    return (unsigned int)(*d3u_ptr(c, a) | ((unsigned int)*d3u_ptr(c, a + 1UL) << 8));
}
static void d3u_st16(dec3w_ctx *c, unsigned long a, unsigned int v)
{
    *d3u_ptr(c, a) = (unsigned char)(v & 0xFFU);
    *d3u_ptr(c, a + 1UL) = (unsigned char)((v >> 8) & 0xFFU);
}
static unsigned int d3u_ld32(dec3w_ctx *c, unsigned long a)
{
    return (unsigned int)(*d3u_ptr(c, a)
        | ((unsigned int)*d3u_ptr(c, a + 1UL) << 8)
        | ((unsigned int)*d3u_ptr(c, a + 2UL) << 16)
        | ((unsigned int)*d3u_ptr(c, a + 3UL) << 24));
}
static void d3u_st32(dec3w_ctx *c, unsigned long a, unsigned int v)
{
    *d3u_ptr(c, a) = (unsigned char)(v & 0xFFU);
    *d3u_ptr(c, a + 1UL) = (unsigned char)((v >> 8) & 0xFFU);
    *d3u_ptr(c, a + 2UL) = (unsigned char)((v >> 16) & 0xFFU);
    *d3u_ptr(c, a + 3UL) = (unsigned char)((v >> 24) & 0xFFU);
}

/* Little-endian u32 read from a lifted const table.  The rep movsd copies
 * at 0x414942/0x4149D9 used to read the slice through d3u_ptr; the source
 * is a read-only table, so the index goes straight into the array. */
static unsigned int d3u_tbl_ld32(const unsigned char *t, unsigned long i)
{
    return (unsigned int)t[i]
        | ((unsigned int)t[i + 1] << 8)
        | ((unsigned int)t[i + 2] << 16)
        | ((unsigned int)t[i + 3] << 24);
}

/* sub_40C9C0-style byte fill (t1=len, t0=dst, t3=val).
 * Must be storage-aware: a fill can run past the end of the globals
 * array into the arena's zero gap, which the port stands in for with
 * one byte, so it stops there. */
void d3uc_fill(dec3w_ctx *c, unsigned int len, unsigned int dst,
              unsigned int val)
{
    unsigned long a = (unsigned long)dst;
    unsigned long n = (unsigned long)len;
    unsigned char v = (unsigned char)(val & 0xFFU);
    while (n > 0) {
        unsigned long chunk;
        unsigned long end;
        if (a >= D3U_GLOBALS_BASE && a < D3U_GLOBALS_END)
            end = D3U_GLOBALS_END;
        else if (a >= D3U_MODEL_BASE && a < D3U_MODEL_BASE + D3U_MODEL_SIZE)
            end = D3U_MODEL_BASE + D3U_MODEL_SIZE;
        else if (a >= D3U_IO_BASE && a < D3U_IO_BASE + D3U_IO_SIZE)
            end = D3U_IO_BASE + D3U_IO_SIZE;
        else {
            /* The rest of a fill that runs past the globals lands in the
             * arena's zero gap, which the port stands in for with one byte,
             * so it is written once and the fill ends there. */
            memset(d3u_ptr(c, a), (int)v, (size_t)1);
            break;
        }
        chunk = n;
        if (a + chunk > end)
            chunk = end - a;
        memset(d3u_ptr(c, a), (int)v, (size_t)chunk);
        a += chunk;
        n -= chunk;
    }
}

